window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[165]={"id":"165","numero":165,"titre":"Oreillons","objectifs":[{"id":"165-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des oreillons","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-etio\">oreillons</span></strong> sont une <strong>infection <span class=\"kw-etio\">virale</span> aiguë</strong>,\n      <strong>contagieuse</strong> et <strong>le plus souvent bénigne</strong>, due au <span class=\"kw-etio\">virus ourlien</span>\n      — un virus à <span class=\"kw-def\">ARN</span> de la famille des <strong><span class=\"kw-etio\">Paramyxoviridae</span></strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Agent</strong></td><td><span class=\"kw-etio\">Virus ourlien</span>, virus à <span class=\"kw-def\">ARN</span>, famille des <span class=\"kw-etio\">Paramyxoviridae</span></td></tr>\n          <tr><td><strong>Réservoir</strong></td><td><span class=\"kw-etio\">Strictement humain</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Épidémiologie</span></strong></td><td>Infection <span class=\"kw-clinique\">endémique</span> dans le monde ; devenue <strong>rare en France</strong> grâce au <span class=\"kw-ttt\">ROR</span> (couverture vaccinale <span class=\"kw-chiffre\">&gt; 95 %</span> dans <span class=\"kw-clinique\">les</span> pays industrialisés) ; <strong><span class=\"kw-alerte\">non éradiquée</span></strong> — couverture encore insuffisante</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Majorité des cas chez l'<strong>enfant</strong> (collectivités, écoles) ; <strong>survenue tardive de plus en plus fréquente</strong> (augmentation de la fréquence <span class=\"kw-etio\">après la puberté</span>)</td></tr>\n          <tr><td><strong>Immunité</strong></td><td><strong>Durable, à vie</strong> après la maladie ; protection vaccinale efficace</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Oreillons = <span class=\"kw-etio\">paramyxovirus</span> à ARN, réservoir <span class=\"kw-etio\">strictement humain</span>,\n        <strong>immunité à vie</strong>. Maladie devenue rare en France grâce au <span class=\"kw-ttt\">ROR</span> mais\n        <strong><span class=\"kw-alerte\">non éradiquée</span></strong> : la couverture vaccinale reste insuffisante pour l'éradication.\n      </div>","frequence":0},{"id":"165-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le tropisme du virus des oreillons et les modalités de transmission","contenu":"<p>Le virus ourlien présente un <strong>double tropisme</strong> : <span class=\"kw-def\">glandulaire</span> et <span class=\"kw-def\">neurologique</span>.</p>\n      <table >\n        <thead><tr><th>Tropisme</th><th>Atteintes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Glandulaire</strong></td><td><span class=\"kw-clinique\">Parotidite</span> ; <span class=\"kw-clinique\">orchite</span> ; <span class=\"kw-clinique\">pancréatite</span></td></tr>\n          <tr><td><strong>Neurologique</strong></td><td><span class=\"kw-etio\">Méningite</span> ; <span class=\"kw-etio\">encéphalite</span> (rarement)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Transmission</strong> interhumaine <strong>directe</strong>, par la salive :</p>\n      <ul>\n        <li><strong>Inhalation de <span class=\"kw-def\">gouttelettes</span> de salive</strong> émises par un sujet malade</li>\n        <li><strong><span class=\"kw-def\">Contact</span> direct avec la salive</strong> d'un sujet malade</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Contagiosité.</strong> Le sujet est contagieux <strong><span class=\"kw-chiffre\">2 jours avant</span></strong> <span class=\"kw-clinique\">les</span> premiers symptômes\n        et <strong><span class=\"kw-chiffre\">4 jours après</span></strong> — d'où une <span class=\"kw-def\">diffusion</span> possible <strong><span class=\"kw-alerte\">avant tout signe clinique</span></strong>.\n      </div>","frequence":1},{"id":"165-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des oreillons","contenu":"<p>Le diagnostic des oreillons est <strong>clinique</strong> dans la forme typique — il repose sur un\n      <span class=\"kw-etio\">contexte évocateur</span> et le tableau de <span class=\"kw-clinique\">parotidite</span>.\n      <span class=\"kw-clinique\">Les</span> examens complémentaires ne sont utiles qu'en cas de doute ou de complication.</p>\n      <p><strong>Contexte évocateur :</strong> <span class=\"kw-etio\">contage récent</span>,\n      <span class=\"kw-etio\">absence ou incomplétude de vaccination</span>, épidémie en saison hivernale.</p>\n      <p><strong>Incubation longue :</strong> environ <strong><span class=\"kw-chiffre\">3 semaines</span></strong>\n      (<span class=\"kw-chiffre\">15 à 25 jours</span>, en moyenne <span class=\"kw-chiffre\">19 jours</span>).</p>\n      <p>L'infection est <strong>asymptomatique dans <span class=\"kw-chiffre\">1/3</span> des cas</strong>. Sinon, l'<span class=\"kw-clinique\">évolution</span> se fait en deux phases :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Invasion</strong></td><td><span class=\"kw-chiffre\">24-48 h</span></td><td><span class=\"kw-clinique\">Fièvre modérée</span> ; <span class=\"kw-clinique\">malaise</span> ; <span class=\"kw-clinique\">gêne à la mastication</span> ; <span class=\"kw-clinique\">otalgie</span></td></tr>\n          <tr><td><strong>État</strong></td><td>≈ <span class=\"kw-chiffre\">1 semaine</span></td><td><span class=\"kw-clinique\">Parotidite ourlienne</span> — présente dans <span class=\"kw-chiffre\">70 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Parotidite ourlienne — sémiologie :</strong></p>\n      <ul>\n        <li>Parotide <span class=\"kw-clinique\">tuméfiée et douloureuse</span>, refoulant le <strong>lobe de l'oreille en haut et en dehors</strong> et comblant le <strong>sillon rétromaxillaire</strong></li>\n        <li>Visage en forme de poire — <strong><span class=\"kw-clinique\">faciès piriforme</span></strong></li>\n        <li>Atteinte <strong>unilatérale puis bilatérale</strong> (bilatéralisation simultanée possible, mais le plus souvent décalée de quelques jours)</li>\n        <li>Turgescence et rougeur de l'ostium du <strong>canal de Sténon</strong> (canal parotidien)</li>\n        <li><span class=\"kw-clinique\">Adénopathies</span> prétragiennes et sous-angulo-maxillaires</li>\n        <li>Signes associés possibles : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">pharyngite</span>, atteinte des glandes salivaires accessoires, <span class=\"kw-clinique\">sécheresse buccale</span></li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> signes généraux sont <strong>peu marqués chez l'enfant</strong>, mais <strong>marqués chez l'adolescent et l'adulte</strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Discriminant — pas d'écoulement.</strong> Dans la parotidite ourlienne, il n'y a\n        <strong><span class=\"kw-alerte\">pas d'écoulement de pus</span></strong> à l'ostium du canal de Sténon : un écoulement\n        purulent oriente vers une <strong>parotidite <span class=\"kw-etio\">bactérienne</span></strong>, pas vers <span class=\"kw-clinique\">les</span> oreillons.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — récidive.</strong> <span class=\"kw-clinique\">Les</span> oreillons confèrent une <strong>immunité à vie</strong> : un\n        <strong>2ᵉ épisode de parotidite aiguë</strong> chez l'enfant <strong><span class=\"kw-alerte\">élimine le diagnostic</span></strong>\n        et doit faire évoquer une autre cause, notamment une <strong>parotidite récurrente juvénile</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 90 — Pathologie des glandes salivaires</em></p>","frequence":0},{"id":"165-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités évolutives des oreillons","contenu":"<p>Dans la <strong>majorité des cas</strong>, <span class=\"kw-clinique\">les</span> oreillons évoluent vers une\n      <strong>guérison spontanée en <span class=\"kw-chiffre\">8 à 10 jours</span></strong>, en dehors de certaines complications.</p>\n      <table >\n        <thead><tr><th>Atteinte</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Parotidite</strong></td><td>Guérison <strong>spontanée</strong> en <span class=\"kw-chiffre\">8-10 jours</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Orchite</span></strong></td><td><span class=\"kw-clinique\">Évolution</span> favorable en <span class=\"kw-chiffre\">1 à 2 semaines</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Pancréatite</span></strong></td><td><strong>Guérison sans séquelle</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Méningite</span></strong></td><td><strong>Guérison sans séquelle</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — complication locale.</strong> Au décours de la parotidite, des <strong><span class=\"kw-clinique\">foyers de nécrose</span></strong>\n        peuvent apparaître et faire le lit d'une <strong><span class=\"kw-alerte\">parotidite chronique</span></strong>.\n      </div>","frequence":1},{"id":"165-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des complications des oreillons","contenu":"<p><span class=\"kw-clinique\">Les</span> complications des oreillons relèvent du <strong>double tropisme</strong> du virus :\n      atteintes <strong>glandulaires</strong> et atteintes <strong>extra-glandulaires (neurologiques)</strong>.</p>\n      <p><strong>Atteintes glandulaires :</strong></p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Fréquence</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Parotidite</strong></td><td><span class=\"kw-chiffre\">70 %</span></td><td>Manifestation typique (cf. rubrique <em><span class=\"kw-def\">Diagnostic positif</span></em>)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Orchite</span> / épididymite</strong></td><td><span class=\"kw-chiffre\">35 %</span></td><td>\n            <strong><span class=\"kw-def\">Terrain</span> :</strong> sujet <strong>pubère</strong> ou adulte jeune (après la puberté)<br>\n            <strong>Délai :</strong> apparaît <span class=\"kw-chiffre\">4 à 8 jours après</span> la parotidite<br>\n            <strong>Latéralité :</strong> <span class=\"kw-clinique\">unilatérale</span> le plus souvent<br>\n            <strong>Clinique :</strong> recrudescence fébrile ; <span class=\"kw-clinique\">douleurs testiculaires à irradiation abdominale</span> ; <span class=\"kw-clinique\">tuméfaction très douloureuse du testicule</span> ; réaction <span class=\"kw-etio\">inflammatoire</span> de la vaginale, du scrotum, voire du cordon spermatique\n          </td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Pancréatite</span></strong></td><td><span class=\"kw-chiffre\">4 %</span></td><td><strong>Asymptomatique le plus souvent</strong> (ou peu sévère) ; <span class=\"kw-radio\">œdémateuse à l'imagerie</span> ; guérison sans séquelle</td></tr>\n          <tr><td><strong>Ovarite, mastite</strong></td><td>Exceptionnelles</td><td>Possibles en période <strong>post-pubertaire</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Atteintes extra-glandulaires (neurologiques) :</strong></p>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Fréquence</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Méningite</span> lymphocytaire</strong></td><td>Fréquente ++</td><td>Souvent <strong>infra-clinique</strong> ; associée dans <span class=\"kw-chiffre\">50 %</span> des cas à une atteinte glandulaire ; <strong>guérison sans séquelle</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Encéphalite</span></strong></td><td>Rare (<span class=\"kw-chiffre\">1 %</span>)</td><td><strong><span class=\"kw-alerte\">Décès dans 1-5 % des cas</span></strong> ; atteinte spécifique du <strong>contingent auditif du nerf VIII</strong> → <strong>surdité possible, parfois définitive</strong></td></tr>\n          <tr><td><strong>Myélite, polyradiculonévrite aiguë</strong></td><td>Possibles</td><td>Atteintes neurologiques plus rares</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Complication grave — <span class=\"kw-etio\">encéphalite</span> ourlienne.</strong> Rare (<span class=\"kw-chiffre\">1 %</span>) mais sévère :\n        <strong><span class=\"kw-alerte\">létalité 1-5 %</span></strong> et atteinte <strong>spécifique du contingent auditif du nerf VIII</strong>,\n        responsable d'une <strong>surdité parfois définitive</strong>. C'est le pivot QCM de l'item.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir — orchite.</strong> L'orchite ourlienne touche le <strong>sujet pubère</strong>, survient\n        <span class=\"kw-chiffre\">4-8 jours après</span> la parotidite et expose à une\n        <strong><span class=\"kw-alerte\">atrophie testiculaire séquellaire dans 50 % des cas</span></strong> — mais la\n        <strong>stérilité reste rare</strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 89 — Altération fonction auditive · 50 — Pathologie génito-scrotale chez le garçon et chez l'homme · 358 — <span class=\"kw-etio\">Pancréatite aiguë</span></em></p>","frequence":2},{"id":"165-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires en cas de suspicion d’oreillons","contenu":"<p>Dans la <strong>forme typique</strong> (parotidite dans un <span class=\"kw-etio\">contexte évocateur</span>), le diagnostic est <strong>clinique</strong> :\n      <strong><span class=\"kw-alerte\">aucun examen complémentaire n'est nécessaire</span></strong>.</p>\n      <p><span class=\"kw-clinique\">Les</span> examens complémentaires ne sont indiqués que dans <strong>deux situations</strong> :</p>\n      <ul>\n        <li>En cas de <strong><span class=\"kw-def\">doute diagnostique</span></strong></li>\n        <li>En cas de <strong>complication</strong>, en particulier une <strong>localisation <span class=\"kw-clinique\">extra-parotidienne</span> isolée</strong>\n        (<span class=\"kw-clinique\">orchite</span>, <span class=\"kw-etio\">méningite</span> ou <span class=\"kw-clinique\">pancréatite</span> sans parotidite associée)</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Devant une parotidite typique de l'enfant en contexte épidémique, on ne demande\n        <strong>rien</strong>. <span class=\"kw-clinique\">Les</span> examens ne servent qu'à trancher un doute ou à documenter une forme <span class=\"kw-clinique\">extra-parotidienne</span> isolée.\n      </div>","frequence":1},{"id":"165-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de confirmation des oreillons","contenu":"<p>La confirmation des oreillons <strong>n'est pas systématique</strong> — elle est réservée aux cas de doute ou de complication.\n      Elle associe une <strong>biologie non spécifique</strong> et une <strong>confirmation virologique</strong>.</p>\n      <p><strong>Biologie non spécifique :</strong></p>\n      <table >\n        <thead><tr><th>Examen</th><th>Résultat</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td><strong>Normale</strong> — <strong><span class=\"kw-alerte\">absence d'hyperleucocytose</span></strong></td></tr>\n          <tr><td><span class=\"kw-bio\">Amylasémie</span></td><td><strong>Hyper-amylasémie</strong> en cas de parotidite ou de pancréatite</td></tr>\n          <tr><td><span class=\"kw-bio\">LCS</span></td><td>En cas de <span class=\"kw-etio\">méningite</span> : liquide <strong>clair « eau de roche »</strong>, <span class=\"kw-bio\">lymphocytaire</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Confirmation virologique</strong> — repose sur la détection du virus, par <strong>2 moyens</strong> :</p>\n      <table >\n        <thead><tr><th>Méthode</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">RT-PCR</span></strong></td><td>\n            <strong>Prélèvements :</strong> <span class=\"kw-bio\">salive</span> ; <span class=\"kw-bio\">LCS</span> ; <span class=\"kw-bio\">urine</span> ; rarement retrouvé dans le sang<br>\n            <strong>Fenêtre :</strong> dans <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-chiffre\">4 premiers jours</span></strong> suivant le début des symptômes\n          </td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Sérologie</span></strong></td><td>\n            Interprétable <strong>en l'absence de <span class=\"kw-ttt\">vaccination</span> antérieure</strong><br>\n            <strong><span class=\"kw-chiffre\">IgM</span> :</strong> détectables quelques jours après l'apparition des premiers signes<br>\n            <strong><span class=\"kw-chiffre\">IgG</span> :</strong> sur 2 prélèvements séparés de <span class=\"kw-chiffre\">15 jours</span> — également spécifique\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — <span class=\"kw-bio\">sérologie</span>.</strong> La <span class=\"kw-bio\">sérologie</span> n'est interprétable que chez le <strong>sujet non vacciné</strong> :\n        chez un vacciné, la <span class=\"kw-bio\">RT-PCR</span> (dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4 premiers jours</span>) doit être privilégiée.\n      </div>","frequence":0},{"id":"165-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités thérapeutique des oreillons","contenu":"<p>Le traitement des oreillons est <strong>uniquement <span class=\"kw-def\">symptomatique</span></strong> — il n'existe pas de traitement <span class=\"kw-ttt\">antiviral</span> spécifique :</p>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Repos</span></strong></li>\n        <li><strong><span class=\"kw-ttt\">Paracétamol</span></strong> (<span class=\"kw-ttt\">antalgique</span> / <span class=\"kw-ttt\">antipyrétique</span>)</li>\n        <li><strong>Port d'un <span class=\"kw-ttt\">suspensoir</span></strong> en cas d'orchite</li>\n      </ul>\n      <p><strong>Mesures en collectivité</strong> — lorsqu'un cas est déclaré :</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Éviction et <span class=\"kw-def\">isolement</span> du cas</strong></td><td><strong><span class=\"kw-alerte\">Non nécessaires</span></strong></td></tr>\n          <tr><td><strong>Sujets contacts</strong></td><td>Aucune mesure spécifique, hormis <strong>informer</strong> de l'existence d'un cas dans la collectivité</td></tr>\n          <tr><td><strong>Fréquentation en phase aiguë</strong></td><td>Néanmoins <strong>pas souhaitable</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Contrairement à l'intuition, l'<strong><span class=\"kw-alerte\">éviction scolaire n'est pas obligatoire</span></strong>\n        et aucune mesure n'est imposée aux sujets contacts — on se contente d'informer la collectivité.\n      </div>","frequence":1},{"id":"165-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les moyens préventifs des oreillons","contenu":"<p>La prévention des oreillons repose <strong>uniquement sur la <span class=\"kw-ttt\">vaccination</span></strong> :</p>\n      <ul>\n        <li>Vaccin <strong><span class=\"kw-ttt\">ROR</span></strong> (<span class=\"kw-etio\">Rougeole</span> - Oreillons - <span class=\"kw-etio\">Rubéole</span>)</li>\n        <li><strong>Il n'existe pas de vaccin <span class=\"kw-def\">monovalent</span></strong> contre <span class=\"kw-clinique\">les</span> oreillons en France</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Prévention = <strong><span class=\"kw-ttt\">ROR</span></strong>, pas de vaccin oreillons isolé.\n        La couverture vaccinale française reste <strong><span class=\"kw-alerte\">insuffisante pour l'éradication</span></strong> :\n        la maladie est devenue rare mais persiste.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-165.pdf","label":"Collège Pilly — Oreillons (item 165, PDF)"}],"cards":[{"i":"42117d388565","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Quel est l'agent causal spécifique des oreillons et ses caractéristiques virologiques ?","a":"<p>L'agent causal des oreillons est le <strong>virus ourlien</strong>, qui est un <strong>virus à ARN</strong> appartenant à la famille des <strong>Paramyxoviridae</strong>.</p>"},{"i":"52161b26f0bb","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Qu'est-ce que la définition médicale des oreillons ?","a":"<p>Les oreillons sont une <strong>infection virale aiguë</strong>, <strong>contagieuse</strong> et le plus souvent <strong>bénigne</strong>, provoquée par le <strong>virus ourlien</strong>.</p>"},{"i":"8b25955ba3aa","n":165,"o":"165-1","u":"Définition","t":"Connaître la définition des oreillons","q":"Quel est le réservoir et le principal terrain d'infection pour les oreillons ?","a":"<p>Le réservoir du virus ourlien est <strong>strictement humain</strong>. La majorité des cas survient chez l'<strong>enfant</strong>, notamment en collectivités, bien que l'on observe une survenue de plus en plus fréquente de cas après la puberté.</p>"},{"i":"5358e94f6d67","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Quel est le signe clinique permettant de différencier une parotidite ourlienne d'une parotidite bactérienne ?","a":"<p>Le signe discriminant est l'<strong>absence d'écoulement purulent</strong> à l'ostium du canal de Sténon dans la parotidite ourlienne. Un écoulement purulent oriente vers une <strong>parotidite bactérienne</strong>.</p>"},{"i":"66915cdb8e8f","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Quel élément clinique écarte le diagnostic d'oreillons et doit faire évoquer une autre pathologie ?","a":"<p>Un <strong>deuxième épisode de parotidite aiguë</strong> chez un patient ayant déjà eu les oreillons écarte le diagnostic, car les oreillons confèrent une immunité à vie. Il faut alors évoquer une autre cause, notamment une <strong>parotidite récurrente juvénile</strong>.</p>"},{"i":"b3adefe35919","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Dans quel cas le diagnostic d'oreillons est-il clinique ?","a":"<p>Le diagnostic des oreillons est clinique dans les <strong>formes typiques</strong>. Il repose sur un <strong>contexte épidémiologique évocateur</strong> (contage, absence de vaccination, épidémie hivernale) et la présence d'une <strong>parotidite</strong>.</p>"},{"i":"be35e9effc48","n":165,"o":"165-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des oreillons","q":"Comment se manifeste une parotidite ourlienne typique au cours des oreillons ?","a":"<p>Une parotidite ourlienne se caractérise par :</p><ul><li>Une <strong>parotide tuméfiée et douloureuse</strong>, refoulant le lobe de l'oreille en haut et en dehors et comblant le sillon rétromaxillaire, donnant un « <strong>faciès piriforme</strong> » (en poire).</li><li>Une atteinte initialement <strong>unilatérale</strong>, puis souvent bilatérale (décalée de quelques jours).</li><li>Une <strong>turgescence et rougeur de l'ostium du canal de Sténon</strong> (sans écoulement purulent).</li><li>Des <strong>adénopathies prétragiennes</strong> et sous-angulo-maxillaires associées.</li></ul>"},{"i":"1dda85eee836","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de l'orchite/épididymite ourlienne ?","a":"<p>L'orchite/épididymite ourlienne survient typiquement chez le sujet <strong>pubère ou adulte jeune</strong>, <strong>4 à 8 jours après la parotidite</strong>. Les signes cliniques incluent :</p><ul><li>Recrudescence fébrile</li><li>Douleurs testiculaires à irradiation abdominale</li><li>Tuméfaction très douloureuse du testicule</li><li>Réaction inflammatoire de la vaginale, du scrotum, et parfois du cordon spermatique</li></ul><p>Elle est le plus souvent <strong>unilatérale</strong> et expose à une atrophie testiculaire séquellaire dans 50 % des cas, mais la stérilité est rare.</p>"},{"i":"33b0bbb8b69f","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de la méningite lymphocytaire ourlienne ?","a":"<p>La méningite lymphocytaire ourlienne est <strong>fréquente</strong>, souvent <strong>infra-clinique</strong>, et associée dans 50 % des cas à une atteinte glandulaire. Elle se caractérise par une guérison sans séquelle.</p>"},{"i":"93efc466c107","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quelle est la particularité clinique de la pancréatite ourlienne ?","a":"<p>La pancréatite ourlienne, qui survient dans <strong>4 %</strong> des cas, est le plus souvent <strong>asymptomatique</strong> ou peu sévère. Elle est de type œdémateuse à l'imagerie et guérit spontanément sans séquelle.</p>"},{"i":"c88dfd341470","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques de l'encéphalite ourlienne ?","a":"<p>L'encéphalite ourlienne est une complication <strong>rare (1 %) mais sévère</strong>. Elle est associée à une <strong>létalité de 1 à 5 %</strong> et se caractérise par une atteinte spécifique du <strong>contingent auditif du nerf VIII</strong>, responsable d'une <strong>surdité parfois définitive</strong>.</p>"},{"i":"d7ffa4fbc2e1","n":165,"o":"165-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des complications des oreillons","q":"Quels sont les signes cliniques des autres atteintes neurologiques rares des oreillons ?","a":"<p>Outre la méningite et l'encéphalite, des atteintes neurologiques plus rares telles que la <strong>myélite</strong> et la <strong>polyradiculonévrite aiguë</strong> sont possibles lors des oreillons.</p>"},{"i":"4c05faa7c9ac","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Quel est le moyen préventif unique des oreillons en France ?","a":"<p>Le seul moyen préventif des oreillons en France est la <strong>vaccination</strong>.</p>"},{"i":"a71918b921ca","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Quel est le vaccin utilisé en France pour la prévention des oreillons ?","a":"<p>Le vaccin utilisé en France pour la prévention des oreillons est le <strong>vaccin trivalent ROR</strong> (Rougeole-Oreillons-Rubéole).</p>"},{"i":"b9786b20ccf4","n":165,"o":"165-9","u":"Prise en charge","t":"Connaître les moyens préventifs des oreillons","q":"Existe-t-il un vaccin monovalent contre les oreillons en France ?","a":"<p>Non, il n'existe <strong>pas de vaccin monovalent</strong> (vaccin isolé) contre les oreillons en France.</p>"}]};